<?php
if (!defined('ABSPATH')) exit;
function sr_lms_input(string $key,string $method='GET'): string {$source=$method==='POST'?$_POST:$_GET;return isset($source[$key])&&is_string($source[$key])?wp_unslash($source[$key]):'';}
function sr_lms_return_url(string $candidate=''): string {
    $fallback=sr_lms_page_url('dashboard');$candidate=trim($candidate);
    if($candidate==='')return $fallback;
    $valid=wp_validate_redirect($candidate,$fallback);if($valid==='')return $fallback;
    $parts=wp_parse_url($valid);if($parts===false)return $fallback;
    if(isset($parts['scheme'])&&!in_array(strtolower($parts['scheme']),['http','https'],true))return $fallback;
    if(!isset($parts['scheme']))return str_starts_with($valid,'/')&&!str_starts_with($valid,'//')?home_url($valid):$fallback;
    return $valid;
}
function sr_lms_email_is_verified(int $user_id): bool { $status=get_user_meta($user_id,'sr_lms_email_verified',true);return $status===''||$status==='1'; }
function sr_lms_send_verification(int $user_id,string $return=''): bool {
    $user=get_userdata($user_id);if(!$user||sr_lms_email_is_verified($user_id))return false;
    try{$token=bin2hex(random_bytes(32));}catch(Throwable $e){return false;}
    update_user_meta($user_id,'sr_lms_email_verify_hash',hash('sha256',$token));update_user_meta($user_id,'sr_lms_email_verify_expires',time()+48*HOUR_IN_SECONDS);
    $url=add_query_arg(['action'=>'sr_lms_verify_email','uid'=>$user_id,'token'=>$token,'return_to'=>sr_lms_return_url($return)],admin_url('admin-post.php'));
    return function_exists('sr_lms_send_email')&&sr_lms_send_email('verification',$user_id,['verify_url'=>$url]);
}
function sr_lms_verify_email_handler(): void {
    $user_id=isset($_GET['uid'])?absint($_GET['uid']):0;$token=isset($_GET['token'])&&is_string($_GET['token'])?sanitize_text_field(wp_unslash($_GET['token'])):'';$user=$user_id?get_userdata($user_id):false;
    if(!$user||!preg_match('/^[a-f0-9]{64}$/D',$token)){wp_safe_redirect(sr_lms_page_url('student-portal',['notice'=>'verification-invalid']));exit;}
    if(sr_lms_email_is_verified($user_id)){wp_safe_redirect(sr_lms_page_url('student-portal',['notice'=>'already-verified']));exit;}
    $saved=(string)get_user_meta($user_id,'sr_lms_email_verify_hash',true);$expires=(int)get_user_meta($user_id,'sr_lms_email_verify_expires',true);
    if(!$saved||!$expires||$expires<time()||!hash_equals($saved,hash('sha256',$token))){wp_safe_redirect(sr_lms_page_url('student-portal',['notice'=>$expires&&$expires<time()?'verification-expired':'verification-invalid','mode'=>'resend']));exit;}
    update_user_meta($user_id,'sr_lms_email_verified','1');delete_user_meta($user_id,'sr_lms_email_verify_hash');delete_user_meta($user_id,'sr_lms_email_verify_expires');wp_set_current_user($user_id);wp_set_auth_cookie($user_id,false,is_ssl());do_action('wp_login',$user->user_login,$user);
    if(function_exists('sr_lms_send_email'))sr_lms_send_email('welcome',$user_id);
    $return=isset($_GET['return_to'])&&is_string($_GET['return_to'])?sr_lms_return_url(wp_unslash($_GET['return_to'])):sr_lms_page_url('dashboard');wp_safe_redirect(add_query_arg('notice','email-verified',$return));exit;
}
function sr_lms_auth_redirect(string $code,string $return='',string $mode='login'): void {wp_safe_redirect(sr_lms_page_url('student-portal',['notice'=>$code,'mode'=>$mode,'redirect_to'=>sr_lms_return_url($return)]));exit;}
function sr_lms_auth_handler(): void {
    if(($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('Use the account form.','Invalid request',['response'=>405]);
    check_admin_referer('sr_lms_auth');$mode=sr_lms_input('mode','POST');$return=sr_lms_return_url(sr_lms_input('redirect_to','POST'));
    if($mode==='logout'){wp_logout();wp_safe_redirect(sr_lms_page_url('student-portal',['notice'=>'logged-out']));exit;}
    if($mode==='resend'){$email=sanitize_email(sr_lms_input('email','POST'));$return=sr_lms_return_url(sr_lms_input('redirect_to','POST'));$user=is_email($email)?get_user_by('email',$email):false;if($user&&!sr_lms_email_is_verified((int)$user->ID)){$sent=(array)get_user_meta($user->ID,'sr_lms_verification_resends',true);$sent=array_values(array_filter($sent,static fn($time)=>is_numeric($time)&&(int)$time>time()-HOUR_IN_SECONDS));if(count($sent)<3){$sent[]=time();update_user_meta($user->ID,'sr_lms_verification_resends',$sent);sr_lms_send_verification((int)$user->ID,$return);}}wp_safe_redirect(sr_lms_page_url('student-portal',['notice'=>'resend-sent']));exit;}
    if(is_user_logged_in()){wp_safe_redirect($return);exit;}
    if($mode==='login'){
        $email=sanitize_email(sr_lms_input('email','POST'));$user=wp_signon(['user_login'=>$email,'user_password'=>sr_lms_input('password','POST'),'remember'=>!empty($_POST['remember'])],is_ssl());
        if(is_wp_error($user))sr_lms_auth_redirect('login-error',$return);
        if(!sr_lms_email_is_verified((int)$user->ID)){wp_logout();sr_lms_auth_redirect('verification-required',$return);}
        if(function_exists('sr_lms_send_email'))sr_lms_send_email('login',(int)$user->ID);
        wp_safe_redirect($return);exit;
    }
    if($mode==='register'){
        if(!get_option('users_can_register'))sr_lms_auth_redirect('registration-disabled',$return,'signup');
        $name=sanitize_text_field(sr_lms_input('name','POST'));$email=sanitize_email(sr_lms_input('email','POST'));$password=sr_lms_input('password','POST');
        if(!$name||!is_email($email)||strlen($password)<10||strlen($password)>4096)sr_lms_auth_redirect('registration-invalid',$return,'signup');
        if(email_exists($email))sr_lms_auth_redirect('registration-error',$return,'signup');
        $username=sanitize_user(strstr($email,'@',true),true);if(!$username)$username='student';$base=$username;$suffix=1;while(username_exists($username))$username=$base.'-'.$suffix++;
        $id=wp_insert_user(['user_login'=>$username,'user_email'=>$email,'user_pass'=>$password,'display_name'=>$name,'first_name'=>$name,'role'=>'subscriber']);
        if(is_wp_error($id))sr_lms_auth_redirect('registration-error',$return,'signup');
        update_user_meta((int)$id,'sr_lms_email_verified','0');$sent=sr_lms_send_verification((int)$id,$return);wp_safe_redirect(sr_lms_page_url('student-portal',['notice'=>$sent?'verification-sent':'verification-mail-error']));exit;
    }
    if($mode==='recover'){
        $email=sanitize_email(sr_lms_input('email','POST'));if(is_email($email))retrieve_password($email);
        sr_lms_auth_redirect('recovery-sent',$return,'recover');
    }sr_lms_auth_redirect('login-error',$return);
}
function sr_lms_guard_pages(): void {
    if(is_page(['learn','dashboard','student-portal','enroll']))sr_lms_private_headers();
    if(is_user_logged_in()&&!sr_lms_email_is_verified(get_current_user_id())&&is_page(['dashboard','enroll','learn'])){wp_logout();wp_safe_redirect(sr_lms_page_url('student-portal',['notice'=>'verification-required','mode'=>'resend']));exit;}
    if(is_page('dashboard')&&!is_user_logged_in()){wp_safe_redirect(sr_lms_page_url('student-portal',['redirect_to'=>sr_lms_page_url('dashboard')]));exit;}
    if(!is_page('learn'))return;
    $course=sr_lms_id(sr_lms_input('course')?:'speakathon');
    if(!$course||!isset(sr_lms_catalog()[$course]))wp_die('This course could not be found.','Course not found',['response'=>404]);
    if(!is_user_logged_in()){wp_safe_redirect(sr_lms_page_url('student-portal',['redirect_to'=>sr_lms_page_url('learn',['course'=>$course])]));exit;}
    if(!sr_lms_has_access(get_current_user_id(),$course)){wp_safe_redirect(sr_lms_page_url('enroll',['course'=>$course,'notice'=>'enrollment-required']));exit;}
}
function sr_lms_enqueue(): void {
    wp_enqueue_style('sr-lms',SR_LMS_URL.'assets/lms.css',[],SR_LMS_VERSION);
    if(!is_page('learn'))return;
    $course=sr_lms_id(sr_lms_input('course')?:'speakathon');$state=sr_lms_student_state(get_current_user_id(),$course);if(!$state)return;
    wp_enqueue_script('sr-lms-player',SR_LMS_URL.'assets/academy-learn.js',[],SR_LMS_VERSION,true);
    wp_add_inline_script('sr-lms-player','window.SR_LMS='.wp_json_encode(['restUrl'=>rest_url('sr-lms/v1/'),'nonce'=>wp_create_nonce('wp_rest'),'state'=>$state,'dashboardUrl'=>sr_lms_page_url('dashboard')],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).';','before');
}
function sr_lms_notice(): void {
    $notices=['login-error'=>'The email or password was not accepted. Please try again.','registration-disabled'=>'Student registration is currently closed. Please contact the academy.','registration-invalid'=>'Enter your name, a valid email and a password of at least 10 characters.','registration-error'=>'We could not create this account. Try signing in or recovering your password.','recovery-sent'=>'If an account matches that address, WordPress will send a password reset link.','logged-out'=>'You have signed out.','requested'=>'Your enrollment request is pending administrator review. No payment has been taken.','enrollment-required'=>'Request enrollment to access this classroom.','invalid-offer'=>'Please choose a course or package.','verification-sent'=>'Your account was created. Check your inbox for a confirmation link before signing in.','verification-mail-error'=>'Your account was created, but the confirmation email could not be sent. Check your address and try resending, or contact the academy.','verification-required'=>'Please confirm your email address before accessing your student account.','verification-expired'=>'That confirmation link has expired. Request a fresh link below.','verification-invalid'=>'That confirmation link is invalid. Request a fresh link below.','already-verified'=>'Your email address is already confirmed. You can sign in.','email-verified'=>'Your email is confirmed. Your student account is ready.','resend-sent'=>'If that address needs confirmation, a fresh email will arrive shortly. Check your inbox and spam folder.' ];
    $notice=sr_lms_input('notice');if(isset($notices[$notice])){echo '<p class="sr-lms-notice" role="status">'.esc_html($notices[$notice]);if(in_array($notice,['verification-required','verification-expired','verification-invalid','verification-mail-error'],true))echo ' <a href="'.esc_url(sr_lms_page_url('student-portal',['mode'=>'resend','redirect_to'=>sr_lms_return_url(sr_lms_input('redirect_to'))])).'">Resend confirmation email</a>';echo '</p>';}
}
function sr_lms_auth_fields(string $mode,string $return): void {echo '<input type="hidden" name="action" value="sr_lms_auth"><input type="hidden" name="mode" value="'.esc_attr($mode).'"><input type="hidden" name="redirect_to" value="'.esc_attr($return).'">';wp_nonce_field('sr_lms_auth');}
function sr_lms_logout_form(): void {echo '<form action="'.esc_url(admin_url('admin-post.php')).'" method="post" class="sr-lms-inline">';sr_lms_auth_fields('logout',sr_lms_page_url('student-portal'));echo '<button class="lms-text-button" type="submit">Sign out</button></form>';}
function sr_lms_profile_handler(): void {
    if(!is_user_logged_in())wp_die('Please sign in to edit your profile.','Account',['response'=>401]);
    check_admin_referer('sr_lms_profile');$user=wp_get_current_user();$email=sanitize_email(sr_lms_input('email','POST'));$first=sanitize_text_field(sr_lms_input('first_name','POST'));$last=sanitize_text_field(sr_lms_input('last_name','POST'));$phone=sanitize_text_field(sr_lms_input('phone','POST'));
    if(!$email||!is_email($email)||($owner=email_exists($email))&&$owner!==(int)$user->ID){wp_safe_redirect(sr_lms_page_url('dashboard',['dashboard_tab'=>'profile','profile_result'=>'invalid']));exit;}
    $display=trim($first.' '.$last);$updated=wp_update_user(['ID'=>$user->ID,'user_email'=>$email,'first_name'=>$first,'last_name'=>$last,'display_name'=>$display?:$user->user_login]);
    if(is_wp_error($updated)){wp_safe_redirect(sr_lms_page_url('dashboard',['dashboard_tab'=>'profile','profile_result'=>'error']));exit;}
    update_user_meta($user->ID,'sr_lms_phone',$phone);wp_safe_redirect(sr_lms_page_url('dashboard',['dashboard_tab'=>'profile','profile_result'=>'saved']));exit;
}
