        if(!is_user_logged_in())echo '<a class="lms-primary" href="'.esc_url(sr_lms_page_url('student-portal',['redirect_to'=>sr_lms_page_url('enroll',['offer'=>$offer])])).'">Sign in to request enrollment →</a>';
        else {
            global $wpdb;$status=$wpdb->get_var($wpdb->prepare('SELECT status FROM '.sr_lms_table('requests').' WHERE user_id=%d AND offer=%s',get_current_user_id(),$offer));$all=true;foreach($selected['courses'] as $slug)if(!sr_lms_has_access(get_current_user_id(),$slug))$all=false;
            if($all)echo '<p>You have access to the included course'.(count($selected['courses'])>1?'s':'').'.</p><a class="lms-primary" href="'.esc_url(sr_lms_page_url('dashboard')).'">Open your dashboard →</a>';
