            else { ?><form action="<?php echo esc_url(admin_url('admin-post.php')); ?>" method="post"><input type="hidden" name="action" value="sr_lms_enroll"><input type="hidden" name="offer" value="<?php echo esc_attr($offer); ?>"><?php wp_nonce_field('sr_lms_enroll'); ?><button class="lms-primary" type="submit">Request enrollment →</button></form><?php }
        } ?></div><?php } ?></div></section><?php
}
function sr_lms_enroll_handler(): void {
    if(($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('Use the enrollment form.','Invalid request',['response'=>405]);check_admin_referer('sr_lms_enroll');$offer=sr_lms_id(sr_lms_input('offer','POST'));
    if(!is_user_logged_in()){wp_safe_redirect(sr_lms_page_url('student-portal',['redirect_to'=>sr_lms_page_url('enroll',['offer'=>$offer])]));exit;}
    if(!sr_lms_email_is_verified(get_current_user_id())){wp_logout();wp_safe_redirect(sr_lms_page_url('student-portal',['notice'=>'verification-required','mode'=>'resend']));exit;}
    if(function_exists('sr_lms_manual_requests_enabled')&&!sr_lms_manual_requests_enabled())wp_die('Manual enrollment requests are disabled. Please use course checkout.','Enrollment',['response'=>403]);
    $result=sr_lms_request_enrollment(get_current_user_id(),$offer);if(is_wp_error($result))wp_die(esc_html($result->get_error_message()),'Enrollment request',['response'=>400]);wp_safe_redirect(sr_lms_page_url('enroll',['offer'=>$offer,'notice'=>'requested']));exit;
}
