    ?><section class="lms-auth-wrap lms-grid-bg"><div class="lms-container sr-dashboard-container"><div class="sr-dashboard-heading"><div><span class="lms-eyebrow">YOUR LEARNING SPACE</span><h1>Welcome back, <?php echo esc_html($user->display_name); ?>.</h1><p>Your course access and progress are saved to your student account.</p></div><div class="sr-dashboard-actions"><?php sr_lms_logout_form(); ?><a href="<?php echo esc_url(sr_lms_page_url('courses')); ?>">Browse courses <span aria-hidden="true">↗</span></a></div></div>
    <nav class="sr-dashboard-tabs" aria-label="Student account sections"><?php foreach($tabs as $key=>$label): ?><a href="<?php echo esc_url(sr_lms_page_url('dashboard',['dashboard_tab'=>$key])); ?>" <?php echo $active===$key?'aria-current="page"':''; ?>><?php echo esc_html($label); ?></a><?php endforeach; ?></nav>
    <?php if($active==='courses'): ?><section class="sr-dashboard-panel" aria-labelledby="sr-dashboard-panel-title"><div class="sr-dashboard-section-heading"><div><span class="lms-eyebrow">PICK UP WHERE YOU LEFT OFF</span><h2 id="sr-dashboard-panel-title">Your courses</h2></div></div><div class="sr-lms-course-grid"><?php $count=0;foreach(sr_lms_catalog() as $slug=>$course){if(!sr_lms_has_access($user->ID,$slug))continue;$count++;$completion=sr_lms_completion($user->ID,$slug); ?><article class="lms-auth-card sr-dashboard-course"><div class="sr-dashboard-course-top"><span class="sr-course-mark" aria-hidden="true"><?php echo esc_html(mb_strtoupper(mb_substr($course['title'],0,1))); ?></span><span class="sr-course-state">ENROLLED</span></div><h3><?php echo esc_html($course['title']); ?></h3><p><?php echo esc_html($course['description']); ?></p><div class="sr-course-progress-label"><span>Course progress</span><strong><?php echo esc_html($completion['percent']); ?>%</strong></div><progress max="100" value="<?php echo esc_attr($completion['percent']); ?>"><?php echo esc_html($completion['percent']); ?>%</progress><p class="sr-course-progress-copy"><?php echo esc_html($completion['completed'].' of '.$completion['total'].' lessons complete'); ?></p><a class="lms-primary full" href="<?php echo esc_url(sr_lms_page_url('learn',['course'=>$slug])); ?>">Continue learning <span aria-hidden="true">→</span></a></article><?php }if(!$count)echo '<article class="sr-dashboard-empty"><span class="lms-eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h3>Build confidence, one lesson at a time.</h3><p>You don’t have a course in your learning space yet. Explore the academy courses to find the right place to begin.</p><a class="lms-primary" href="'.esc_url(sr_lms_page_url('courses')).'">Explore courses <span aria-hidden="true">→</span></a></article>'; ?></div></section>
    <?php elseif($active==='profile'): ?><section class="sr-dashboard-panel sr-profile-panel"><span class="lms-eyebrow">ACCOUNT DETAILS</span><h2>Keep your profile up to date</h2><p>These details are used for your course access and completion certificates.</p><?php $profile_result=sr_lms_input('profile_result');if($profile_result==='saved')echo '<p class="sr-lms-notice" role="status">Your profile has been updated.</p>';elseif($profile_result==='invalid'||$profile_result==='error')echo '<p class="sr-lms-notice" role="alert">We could not save those details. Check the email address and try again.</p>'; ?><form class="sr-profile-form" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" method="post"><input type="hidden" name="action" value="sr_lms_profile"><?php wp_nonce_field('sr_lms_profile'); ?><label>First name<input name="first_name" autocomplete="given-name" maxlength="60" value="<?php echo esc_attr($user->first_name); ?>" required></label><label>Last name<input name="last_name" autocomplete="family-name" maxlength="60" value="<?php echo esc_attr($user->last_name); ?>"></label><label>Email address<input name="email" type="email" autocomplete="email" maxlength="100" value="<?php echo esc_attr($user->user_email); ?>" required></label><label>Phone number <span>(optional)</span><input name="phone" type="tel" autocomplete="tel" maxlength="40" value="<?php echo esc_attr(get_user_meta($user->ID,'sr_lms_phone',true)); ?>"></label><p class="sr-profile-note">To change your password, use <a href="<?php echo esc_url(wp_lostpassword_url()); ?>">password reset</a>.</p><button class="lms-primary" type="submit">Save profile</button></form></section>
    <?php elseif($active==='certificates'): ?><section class="sr-dashboard-panel"><span class="lms-eyebrow">MILESTONES</span><h2>Your certificates</h2><p class="sr-dashboard-intro">Certificates become available after all required lesson recordings and practice are complete.</p><div class="sr-certificate-list"><?php $earned=0;foreach(sr_lms_catalog() as $slug=>$course){if(!sr_lms_has_access($user->ID,$slug))continue;$completion=sr_lms_completion($user->ID,$slug);if(!$completion['eligible'])continue;$earned++; ?><article><span class="sr-certificate-icon" aria-hidden="true">✦</span><div><strong><?php echo esc_html($course['title']); ?></strong><span>Course completion certificate</span></div><a class="lms-primary" target="_blank" rel="noopener" href="<?php echo esc_url(add_query_arg(['action'=>'sr_lms_certificate','course'=>$slug],admin_url('admin-post.php'))); ?>">View certificate ↗</a></article><?php }if(!$earned)echo '<div class="sr-dashboard-empty"><h3>Your next achievement is in progress</h3><p>Complete every required recording and practice acknowledgement in an enrolled course. Your certificate will appear here automatically.</p><a href="'.esc_url(sr_lms_page_url('dashboard',['dashboard_tab'=>'courses'])).'">Continue a course →</a></div>'; ?></div></section>
    <?php else: global $wpdb;$requests=$wpdb->get_results($wpdb->prepare('SELECT offer,status,updated_at FROM '.sr_lms_table('requests').' WHERE user_id=%d ORDER BY updated_at DESC',get_current_user_id()),ARRAY_A);$payments=$wpdb->get_results($wpdb->prepare('SELECT offer,amount,status,created_at FROM '.sr_lms_table('payments').' WHERE user_id=%d ORDER BY created_at DESC LIMIT 20',get_current_user_id()),ARRAY_A); ?><section class="sr-dashboard-panel"><span class="lms-eyebrow">RECENT ACCOUNT HISTORY</span><h2>Account activity</h2><div class="sr-activity-block"><h3>Enrollment requests</h3><?php if($requests): ?><ul class="sr-activity-list"><?php foreach($requests as $request): ?><li><span><?php echo esc_html(sr_lms_offers()[$request['offer']]['title']??$request['offer']); ?></span><span class="sr-activity-status"><?php echo esc_html(ucfirst($request['status'])); ?></span><time><?php echo esc_html(wp_date(get_option('date_format'),strtotime($request['updated_at'].' UTC'))); ?></time></li><?php endforeach; ?></ul><?php else: ?><p>No enrollment requests yet.</p><?php endif; ?></div><div class="sr-activity-block"><h3>Course purchases</h3><?php if($payments): ?><ul class="sr-activity-list"><?php foreach($payments as $payment): ?><li><span><?php echo esc_html(sr_lms_offers()[$payment['offer']]['title']??$payment['offer']); ?></span><span class="sr-activity-status"><?php echo esc_html(ucfirst(str_replace('_',' ',$payment['status']))); ?></span><time>₹<?php echo esc_html(number_format_i18n(((int)$payment['amount'])/100,2)); ?> · <?php echo esc_html(wp_date(get_option('date_format'),strtotime($payment['created_at'].' UTC'))); ?></time></li><?php endforeach; ?></ul><?php else: ?><p>No online purchases yet.</p><?php endif; ?></div><div class="sr-account-help"><strong>Need help with your account?</strong><p>Contact the academy if you need help with access, a purchase, or your student details.</p><a href="<?php echo esc_url(sr_theme_url('contact.html')); ?>">Contact the academy →</a></div></section><?php endif; ?></div></section><?php
}
